import base64
import ipaddress
import json
import time
from urllib.parse import urlsplit

import httpx
import perceivo

_METHODS = ("GET", "POST", "PUT", "PATCH", "DELETE", "HEAD")
_AUTH_TYPES = ("none", "bearer_token", "api_key_header", "basic_auth")
_RESPONSE_TYPES = ("auto", "json", "text")
_FALSY = ("false", "0", "no", "off")
_HEADER_NAME_PUNCTUATION = "!#$%&'*+-.^_`|~"
_HOST_CHARS = frozenset("abcdefghijklmnopqrstuvwxyz0123456789.-_")
_BAD_URL = (
    "The URL is not valid. Check Base URL and request_data.url. If it holds a username "
    "and password, remove them and use Authentication instead. The URL is not shown "
    "because it can carry a credential."
)


def _param(name: str, default: str = "") -> str:
    return str(perceivo.params.get(name, default) or default).strip()


def _flag(name: str, default: bool) -> bool:
    value = perceivo.params.get(name, default)
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() not in _FALSY


def _scheme_note(base_url: str) -> str:
    """', not ftp://' when base_url opens with a well-formed scheme, else ''."""
    head, sep, _ = base_url.partition("://")
    token = head.replace("+", "").replace("-", "").replace(".", "")
    if sep and head[:1].isalpha() and len(head) <= 16 and token.isascii() and token.isalnum():
        return f", not {head.lower()}://"
    return ""


def _resolve_url(base_url: str, url: str) -> str:
    """An absolute url is used as given; anything else is a path under base_url."""
    url = (url or "").strip()
    if url.lower().startswith(("http://", "https://")):
        return url
    if not base_url:
        raise ValueError(
            "No URL. Set Base URL in the Inspector, or send an absolute url in request_data."
        )
    if not base_url.lower().startswith(("http://", "https://")):
        # Base URL can carry user:password@ or a key in its query string, and an
        # error message is stored and shown; only its scheme is named.
        raise ValueError(
            f"Base URL must start with http:// or https://{_scheme_note(base_url)}."
        )
    if not url:
        return base_url
    return base_url.rstrip("/") + "/" + url.lstrip("/")


def _split(url: str):
    """urlsplit(url) and its port, with the parser's own error replaced.

    The parser quotes the part it cannot read, and for a URL whose password
    holds an unencoded #, / or ? that part is the password.
    """
    try:
        parts = urlsplit(url)
        return parts, parts.port
    except ValueError:
        raise ValueError(_BAD_URL) from None


def _plain_host(host: str) -> bool:
    """A DNS name or IPv4 literal, or an IPv6 literal without a zone."""
    if set(host) <= _HOST_CHARS:
        return True
    # Checked before ip_address(), which accepts a zone: fe80::1%admin:hunter2.
    if not set(host) <= _HOST_CHARS | {":"}:
        return False
    try:
        ipaddress.ip_address(host)
    except ValueError:
        return False
    return True


def _under_base(base_url: str, target) -> bool:
    """True when target is on Base URL's scheme, host and port, at or below its path."""
    if not base_url:
        return False
    base, _ = _split(base_url)
    if (base.scheme.lower(), base.netloc.lower()) != (target.scheme.lower(), target.netloc.lower()):
        return False
    prefix = base.path.rstrip("/")
    return not prefix or target.path == prefix or target.path.startswith(prefix + "/")


def _default_headers() -> dict:
    raw = _param("default_headers", "{}") or "{}"
    try:
        headers = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Default Headers is not valid JSON: {exc.msg}.") from None
    if not isinstance(headers, dict):
        raise ValueError(
            'Default Headers must be a JSON object, e.g. {"Accept": "application/json"}.'
        )
    return _clean_headers(headers, "Default Headers")


def _clean_headers(headers: dict, source: str) -> dict:
    """headers with each name and value trimmed; refused when one is not valid HTTP.

    The HTTP client quotes a header it refuses, and a header can be the
    credential. The check is made here so that nothing of it reaches an error.
    """
    clean = {}
    for key, value in headers.items():
        name, text = str(key).strip(), str(value).strip()
        name_ok = (
            bool(name)
            and name.isascii()
            and all(char.isalnum() or char in _HEADER_NAME_PUNCTUATION for char in name)
        )
        text_ok = all(char == "\t" or " " <= char <= "~" for char in text)
        if not (name_ok and text_ok):
            raise ValueError(
                f"{source}: a header name or value is not valid HTTP, for example it holds "
                "a line break or a character outside ASCII. It is not shown because a "
                "header can carry a credential."
            )
        clean[name] = text
    return clean


async def _auth_header(auth_type: str) -> dict:
    """The credential header for auth_type. The token is the auth_token secret."""
    if auth_type == "none":
        return {}
    # A secret pasted with a trailing line break is still the same secret. A
    # basic credential loses only line breaks: a space at either end belongs to
    # the username or the password, and removing it would change what is sent.
    stored = str(await perceivo.secrets.get("auth_token") or "")
    token = stored.strip("\r\n") if auth_type == "basic_auth" else stored.strip()
    if not token.strip():
        raise ValueError(
            f"Authentication is {auth_type} but no auth_token secret is bound. Bind one "
            "in the Inspector, or set Authentication to none."
        )
    if auth_type == "bearer_token":
        return {"Authorization": f"Bearer {token}"}
    if auth_type == "api_key_header":
        return {_param("auth_header_name", "X-API-Key") or "X-API-Key": token}
    if ":" not in token:
        raise ValueError("Basic authentication needs the auth_token secret as username:password.")
    return {"Authorization": "Basic " + base64.b64encode(token.encode()).decode()}


def _parse_data(response: httpx.Response, response_type: str, success: bool) -> dict:
    """The body parsed as JSON, always as an object, per Response Type.

    auto parses when the server says it sent JSON; json always parses; text
    never does. A JSON array arrives as {"items": [...]} and a JSON scalar as
    {"value": ...}, so `data` is an object whatever the server sent; {} means
    the body was not JSON. json insists on JSON for a successful response; an
    error response that is not JSON gives {} instead, so the status code is
    never hidden behind a parse error.
    """
    content_type = response.headers.get("content-type", "")
    wants_json = response_type == "json" or (
        response_type == "auto" and "json" in content_type.lower()
    )
    if not wants_json or not response.content:
        return {}
    try:
        parsed = response.json()
    except ValueError:
        if response_type == "json" and success:
            raise ValueError(
                f"Response Type is json but the {response.status_code} response is not "
                f"valid JSON (Content-Type {content_type or 'unset'})."
            ) from None
        return {}
    if isinstance(parsed, dict):
        return parsed
    if isinstance(parsed, list):
        return {"items": parsed}
    return {"value": parsed}


@perceivo.tool
async def http_request(input: perceivo.primitives.ToolInput) -> perceivo.primitives.ToolOutput:
    """Make one outbound HTTP request and return the response as data.

    The method, base URL, headers, authentication and timeout are node
    parameters; request_data may supply the url (absolute, or a path under the
    base URL), override the method, and add headers, query parameters and a
    body. The credential is the optional `auth_token` secret, read by NAME.

    An HTTP error status is a RESULT, not a failure: it is returned with
    success false so the next node can branch on it. Anything that means no
    response was obtained -- bad configuration, a refused route, a timeout --
    raises and fails the run.
    """
    data = input.request_data or {}
    if not isinstance(data, dict):
        data = {}

    method = str(data.get("method") or _param("method", "GET")).strip().upper()
    if method not in _METHODS:
        raise ValueError(f"Method is {method!r}. Choose one of: {', '.join(_METHODS)}.")

    url = _resolve_url(_param("base_url"), str(data.get("url") or ""))
    parts, port = _split(url)

    auth_type = _param("auth_type", "none").lower()
    if auth_type not in _AUTH_TYPES:
        raise ValueError(
            f"Authentication is {auth_type!r}. Choose one of: {', '.join(_AUTH_TYPES)}."
        )
    # request_data can come from upstream nodes, LLM output included, so an
    # absolute url there must not carry the bound credential to another host.
    if auth_type != "none" and not _under_base(_param("base_url"), parts):
        raise ValueError(
            "Authentication sends the auth_token secret, so the url must be under Base URL. "
            "Set Base URL to the host you authenticate to, or send a path rather than an "
            "absolute url."
        )

    response_type = _param("response_type", "auto").lower()
    if response_type not in _RESPONSE_TYPES:
        raise ValueError(
            f"Response Type is {response_type!r}. Choose one of: {', '.join(_RESPONSE_TYPES)}."
        )

    # Read raw: _param would turn an explicit 0 into the default.
    raw_timeout = perceivo.params.get("timeout_seconds", 30)
    try:
        timeout = float(
            30 if raw_timeout is None or str(raw_timeout).strip() == "" else raw_timeout
        )
    except ValueError:
        raise ValueError("Timeout must be a number of seconds.") from None
    if timeout <= 0:
        raise ValueError("Timeout must be greater than zero.")

    headers = _default_headers()
    headers.update(_clean_headers(await _auth_header(auth_type), "Authentication"))
    extra = data.get("headers")
    if isinstance(extra, dict):
        headers.update(_clean_headers(extra, "request_data headers"))

    query = data.get("query_params")
    params = query if isinstance(query, dict) and query else None

    body, body_text = data.get("body"), data.get("body_text")
    if body is not None and body_text is not None:
        raise ValueError("Send body (JSON) or body_text, not both.")
    send = {}
    if body is not None:
        send["json"] = body
    elif body_text is not None:
        send["content"] = str(body_text)
    # Encoded as the HTTP client will (httpx 0.28: UTF-8, ensure_ascii=False),
    # so that its UnicodeError, caught below as a bad URL or header, cannot come
    # from the body.
    try:
        if "json" in send:
            json.dumps(send["json"], ensure_ascii=False, allow_nan=False).encode("utf-8")
        elif "content" in send:
            send["content"].encode("utf-8")
    except UnicodeError:
        raise ValueError(
            "The body cannot be sent: it holds text that is not valid Unicode, such as "
            "half of a surrogate pair."
        ) from None

    # The path (a webhook keeps its key there), the query string, the
    # user:password@ part and the headers can carry credentials; none of them
    # is logged. A URL with an @ anywhere is logged without its host, because a
    # badly written user:password@ can parse as the host. That includes an @ in
    # the path or query, such as an e-mail address: https://user:8443/x@host
    # puts a password where the port goes, and nothing in the text tells the two
    # apart. A host that is not a plain name -- user%3Apass%40host is a
    # percent-encoded credential, and [user:pass] parses as a bracketed host --
    # is not logged either.
    host = parts.hostname or ""
    if "@" in url:
        logged_url = f"{parts.scheme}://(host not logged: the URL contains @)"
    elif not _plain_host(host):
        logged_url = f"{parts.scheme}://(host not logged: not a plain host name)"
    else:
        logged_url = f"{parts.scheme}://{host}"
        if port:
            logged_url += f":{port}"
    perceivo.log.info(
        f"HTTP Request: {method} {logged_url}",
        method=method,
        has_body=bool(send),
        header_count=len(headers),
    )

    wait = _flag("wait_for_response", True)
    started = time.monotonic()
    # Redirects are not followed: the guarded client validates each destination
    # against the organization's outbound routes and refuses follow_redirects.
    # Streaming lets webhook mode return on the status line without downloading
    # the body; otherwise the whole body is read before the client closes.
    try:
        async with (
            httpx.AsyncClient(timeout=timeout) as client,
            client.stream(method, url, headers=headers, params=params, **send) as response,
        ):
            if wait:
                await response.aread()
    except (httpx.InvalidURL, httpx.LocalProtocolError, UnicodeError):
        # These quote the URL or header bytes they refuse. The body was encoded
        # above, so a UnicodeError here is the URL's: its host or query string.
        raise ValueError(
            "The request could not be built: the URL or a header is not valid HTTP. "
            "Neither is shown because either can carry a credential."
        ) from None
    elapsed_ms = round((time.monotonic() - started) * 1000)

    status_code = response.status_code
    success = status_code < 400
    content_type = response.headers.get("content-type", "")
    text = response.text if wait else ""
    parsed = _parse_data(response, response_type, success) if wait else {}

    perceivo.log.info(
        f"HTTP Request: {status_code} in {elapsed_ms} ms",
        status_code=status_code,
        success=success,
        elapsed_ms=elapsed_ms,
    )

    return perceivo.primitives.ToolOutput(
        response_data={
            "status_code": status_code,
            "success": success,
            "body": text,
            "data": parsed,
            "headers": dict(response.headers.items()),
            "content_type": content_type,
            "elapsed_ms": elapsed_ms,
            "error": "" if success else f"HTTP {status_code} {response.reason_phrase}".strip(),
        },
    )
